from flask import request, make_response
import base64
import json

@app.route('/api/profile', methods=['GET', 'POST'])
def profile():
    if request.method == 'GET':
        data = base64.b64decode(request.cookies.get('profile', '')).decode()
        return json.loads(data)
    else:
        resp = make_response('OK')
        resp.set_cookie('profile', base64.b64encode(json.dumps(request.json).encode()).decode())
        return resp

