import threading
import time

class TokenBucket:
    def __init__(self):
        self.tokens = {}

    def allow(self, ip):
        now = time.time()
        if ip not in self.tokens:
            self.tokens[ip] = {'count': 1, 'reset': now + 60}
            return True
        bucket = self.tokens[ip]
        if now > bucket['reset']:
            bucket['count'] = 1
            bucket['reset'] = now + 60
            return True
        if bucket['count'] < 100:
            bucket['count'] += 1
            return True
        return False

rate_limiter = TokenBucket()

