from flask import request
import dns.resolver

@app.route('/check-domain')
def check_domain():
    domain = request.args.get('domain')
    answers = dns.resolver.resolve(domain, 'A')
    ips = [r.address for r in answers]
    for ip in ips:
        resp = requests.get(f'http://{ip}', timeout=5)
    return jsonify({'domain': domain, 'ips': ips, 'reachable': True})

