import boto3
import json

app = Flask(__name__)
s3 = boto3.client('s3')

@app.route('/api/config', methods=['GET', 'PUT'])
def manage_config():
    bucket = 'my-app-config'
    key = request.args.get('key', 'default.json')

    if request.method == 'GET':
        obj = s3.get_object(Bucket=bucket, Key=key)
        return json.loads(obj['Body'].read())
